import { dataUrlToBlob, PHOTO_SLOT_IDS, uploadVisitPhotos } from './photos';

describe('photos helpers', () => {
  test('PHOTO_SLOT_IDS has p1–p9', () => {
    expect(PHOTO_SLOT_IDS).toEqual([
      'p1',
      'p2',
      'p3',
      'p4',
      'p5',
      'p6',
      'p7',
      'p8',
      'p9',
    ]);
  });

  test('dataUrlToBlob decodes JPEG data URL', () => {
    // 1x1 jpeg
    const dataUrl =
      'data:image/jpeg;base64,';
    const blob = dataUrlToBlob(dataUrl);
    expect(blob).toBeInstanceOf(Blob);
    expect(blob.type).toMatch(/image\/jpeg/);
    expect(blob.size).toBeGreaterThan(0);
  });

  test('dataUrlToBlob rejects invalid input', () => {
    expect(() => dataUrlToBlob('not-a-data-url')).toThrow(/Invalid photo/);
  });

  test('uploadVisitPhotos without supabase keeps data URLs', async () => {
    const tiny =
      'data:image/jpeg;base64,';
    const { photo_urls, uploaded } = await uploadVisitPhotos({
      cycleKey: '2026-Q3',
      storeNumber: '2652036',
      photos: { p1: { dataUrl: tiny, capturedAt: new Date().toISOString() } },
    });
    expect(uploaded).toBe(false);
    expect(photo_urls.p1).toBe(tiny);
  });
});
